task.setup:
sim.user.config["user.name"] = "Anna Karimova";
sim.user.config["user.email"] = "anna@example.com";
sim.user.config["init.defaultBranch"] = "main";
sim.createRemote("https://github.com/team/site.git", { readme: true });
// ученик клонировал общий репозиторий и сделал локальный коммит (ещё не отправлен)
sim.run(`git clone https://github.com/team/site.git
cd site
echo "<h1>Team site</h1>" > index.html
echo "# Notes" > notes.md
echo "- add contacts page" >> notes.md
git add . && git commit -m "Add home page"`, { quiet: true });
// товарищ по команде клонировал, изменил другой файл и отправил push
sim.addUser("aziz", { name: "Aziz Rakhimov", email: "aziz@example.com", defaultBranch: "main" });
sim.run(`git clone https://github.com/team/site.git
cd site
echo "body { margin: 0; }" > style.css
git add . && git commit -m "Add styles"
git push`, { user: "aziz", quiet: true });
// у ученика ещё есть незакоммиченная правка
sim.run(`echo "- add footer" >> notes.md`, { quiet: true });

